const express = require('express');
const session = require('express-session');
const { scrypt, randomBytes, timingSafeEqual } = require('node:crypto');
const { promisify } = require('node:util');

const scryptAsync = promisify(scrypt);

if (!process.env.SESSION_SECRET) throw new Error('SESSION_SECRET is required');

// --- Password hashing (scrypt, OWASP params: N=2^14, r=8, p=5) ---

const SCRYPT_OPTS = { N: 2 ** 14, r: 8, p: 5 };

async function hashPassword(password) {
  const salt = randomBytes(16);
  const key = await scryptAsync(password, salt, 64, SCRYPT_OPTS);
  return `${salt.toString('hex')}:${key.toString('hex')}`;
}

async function verifyPassword(password, stored) {
  const [salt, key] = stored.split(':').map((h) => Buffer.from(h, 'hex'));
  return timingSafeEqual(key, await scryptAsync(password, salt, 64, SCRYPT_OPTS));
}

// Verified against when the user doesn't exist, so response time doesn't reveal valid usernames.
const dummyHash = hashPassword(randomBytes(16).toString('hex'));

// --- Failed-attempt rate limiting ---

const WINDOW_MS = 15 * 60 * 1000;
const MAX_PER_IP_USER = 5; // stops guessing one account
const MAX_PER_IP = 50; // stops spraying one password across many accounts

// chisle: in-memory, single process; move to Redis when running more than one instance
const fails = new Map(); // key -> { count, resetAt }

// Counts the attempt up front (so parallel requests can't slip past the limit)
// and returns seconds until retry is allowed, or 0 if under the limit.
function hit(key, max) {
  const now = Date.now();
  let entry = fails.get(key);
  if (!entry || entry.resetAt <= now) {
    entry = { count: 0, resetAt: now + WINDOW_MS };
    fails.set(key, entry);
  }
  return ++entry.count <= max ? 0 : Math.ceil((entry.resetAt - now) / 1000);
}

setInterval(() => {
  const now = Date.now();
  for (const [key, entry] of fails) if (entry.resetAt <= now) fails.delete(key);
}, WINDOW_MS).unref();

// --- App ---

// chisle: in-memory users; swap for a DB with a unique index on username
const users = new Map(); // username -> { id, username, hash }

const app = express();
// Behind a reverse proxy, set this so req.ip is the client and secure cookies work:
// app.set('trust proxy', 1);
app.use(express.json());
app.use(
  session({
    secret: process.env.SESSION_SECRET,
    name: 'sid',
    resave: false,
    saveUninitialized: false,
    // chisle: default MemoryStore leaks and is per-process; use connect-redis or similar in production
    cookie: {
      httpOnly: true,
      sameSite: 'lax',
      secure: process.env.NODE_ENV === 'production',
      maxAge: 8 * 60 * 60 * 1000,
    },
  })
);

function credentials(req) {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string') return null;
  if (!username || username.length > 254 || password.length > 1024) return null;
  return { username: username.toLowerCase(), password };
}

app.post('/register', async (req, res) => {
  const creds = credentials(req);
  if (!creds || creds.password.length < 8) return res.status(400).json({ error: 'Invalid request' });
  if (users.has(creds.username)) return res.status(409).json({ error: 'Username taken' });
  const hash = await hashPassword(creds.password);
  users.set(creds.username, { id: randomBytes(8).toString('hex'), username: creds.username, hash });
  res.status(201).json({ ok: true });
});

app.post('/login', async (req, res, next) => {
  const creds = credentials(req);
  if (!creds) return res.status(400).json({ error: 'Invalid request' });

  const ipKey = `ip:${req.ip}`;
  const pairKey = `${req.ip}|${creds.username}`;
  const retryAfter = Math.max(hit(ipKey, MAX_PER_IP), hit(pairKey, MAX_PER_IP_USER));
  if (retryAfter) {
    return res.set('Retry-After', String(retryAfter)).status(429).json({ error: 'Too many attempts' });
  }

  const user = users.get(creds.username);
  const ok = await verifyPassword(creds.password, user?.hash ?? (await dummyHash));
  if (!user || !ok) return res.status(401).json({ error: 'Invalid username or password' });

  // Success: only failures should count.
  fails.delete(pairKey);
  const ipEntry = fails.get(ipKey);
  if (ipEntry) ipEntry.count--;

  // New session ID on login prevents session fixation.
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.userId = user.id;
    res.json({ ok: true });
  });
});

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'Not authenticated' });
  next();
}

app.get('/me', requireAuth, (req, res) => res.json({ userId: req.session.userId }));

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid').json({ ok: true });
  });
});

if (require.main === module) app.listen(3000, () => console.log('listening on :3000'));

module.exports = app;

process.env.SESSION_SECRET = 'test-secret';
const test = require('node:test');
const assert = require('node:assert');
const app = require('./app');

test('login, session, rate limit', async () => {
  const server = app.listen(0);
  const base = `http://localhost:${server.address().port}`;
  const post = (path, body, cookie) =>
    fetch(base + path, {
      method: 'POST',
      headers: { 'content-type': 'application/json', ...(cookie && { cookie }) },
      body: JSON.stringify(body),
    });

  try {
    for (const username of ['alice', 'bob']) {
      assert.equal((await post('/register', { username, password: 'correct horse' })).status, 201);
    }

    // Session lifecycle
    const login = await post('/login', { username: 'alice', password: 'correct horse' });
    assert.equal(login.status, 200);
    const cookie = login.headers.get('set-cookie').split(';')[0];
    assert.equal((await fetch(base + '/me', { headers: { cookie } })).status, 200);
    assert.equal((await fetch(base + '/me')).status, 401);
    assert.equal((await post('/logout', {}, cookie)).status, 200);
    assert.equal((await fetch(base + '/me', { headers: { cookie } })).status, 401);

    // Unknown user and wrong password are indistinguishable
    assert.equal((await post('/login', { username: 'nobody', password: 'x' })).status, 401);

    // 5 failures lock the account for this IP, even with the right password
    for (let i = 0; i < 5; i++) {
      assert.equal((await post('/login', { username: 'bob', password: 'wrong' })).status, 401);
    }
    const locked = await post('/login', { username: 'bob', password: 'correct horse' });
    assert.equal(locked.status, 429);
    assert.ok(Number(locked.headers.get('retry-after')) > 0);

    // Other accounts unaffected
    assert.equal((await post('/login', { username: 'alice', password: 'correct horse' })).status, 200);
  } finally {
    server.close();
  }
});

